    "exampleHash": "261d369138088df6b64a43fa2ec32125963f490e28e40d8cb5b8134596ffe818",
    "qa": "pass",
    "qaDetail": "メモラ君の木工作業の切り口から細かいおがくずが出て、タヌキの小さな荷車を満たす。主製品と副産物、両者の手と文字なしを確認。",
    "sha256": "18ee2926d8500b85d86b510da8c28f52d98ab0a8f88feef6837a6fcb398351a8",
    "width": 800,
    "height": 533
