    "qa": "pass",
    "qaDetail": "メモラ君の口を開いた詠唱姿勢と、頭から浮いて傾いた帽子だけが反応する場面を確認。固有キャラ・文字なし・四肢を確認。",
    "sha256": "e21298fbe0a6b36829ee94ed5f0296175056303742e2c1b04a3787be5ada9069",
    "width": 800,
    "height": 533
