    "exampleHash": "8ec880cc173f7ac39ef319c0eb0b7f4dad9a4a2d3dd7031bda3c8fe4f1a49165",
    "qa": "pass",
    "qaDetail": "既存の丸パン・細長いパン等にメモラ君が長靴型の焼き色の付いたパンを追加する。実際の靴ではなくパンと分かり、商品の多様化に対応。",
    "sha256": "a9aac47c51ee1f3a38cce63174546bf199f61074886858b70483c545e151a02d",
