    "qa": "pass",
    "qaDetail": "1場面。開いた1本の傘が雨を遮り、同じ長い軸のゴム先を地面について歩行の支えにもする。メモラ君1人、連続した軸、手と地面への接触、両用途の同時性を確認。",
    "sha256": "96fcc901848c7ca10bc8dd857b63c396c3c3e5261a70a76574f46510ddb28be6",
