    "exampleHash": "5570225be8f5c057f220295c8c8ebd2b857eee75d6ae502a9c937bb3510efd0a",
    "qa": "pass",
    "qaDetail": "空の奥深い洞窟へメモラ君が手を振り、もう一方の手を耳に当てて呼びかける。反響を聞いて再び挨拶する例文の状況を示し、別の応答人物や文字なし。",
    "sha256": "19c48aba2c1de63e9114fcdb90a96588ec4e61cb9892f867e360efe6062ce42b",
