    "qa": "pass",
    "qaDetail": "1場面。停止した車輪付き浴槽の縁でメモラ君が聞き、タヌキが身ぶりで出来事を語り直す。背景の坂道と同じ空間。回想枠・別の浴槽・同一キャラ複製なし。",
    "sha256": "4809393de44488fe8c26999df8e9223d58bc83badf93af17de28fa66196c7293",
