    "exampleHash": "1851264e82732f01dad16d476120353ab6dbfcbda59cbb24faf1254b3bcef58c",
    "qa": "pass",
    "qaDetail": "タヌキが注ぐホットチョコレートの液面がメモラ君のカップの縁まで達する。注ぐ動作・持ち手・接触が自然。",
    "sha256": "ae67c34339f5d35ff5e73479602f7c59059f9cbe279b7f36f2089801a54eade7",
