    "exampleHash": "f9fc0141e34e78ebad4abb2884c1d6a01f8de4f767385cd2b4947125c90793b9",
    "qa": "pass",
    "qaDetail": "大きな傘をタヌキへ譲り、メモラ君は小さい傘を持つ同じ玄関の場面。傘は2本、所有と受け渡しが明瞭。",
    "sha256": "3b78ca4d302d68c3bcdda2da29f4e763a0663ff4577b6b90b361d6a332fbb586",
