    "exampleHash": "f3743768622cb08ff7eea5d7a885e31113bb27678fe6bf9c28c52ca67e45d4aa",
    "qa": "pass",
    "qaDetail": "メモラ君が安全な岸から長い棒を伸ばし、小さな橋の板に先端を触れさせて確認。1本の川と橋の連続場面。",
    "sha256": "cccadd6ad1daf519055115c3d52a722c84ed5f8ea64acc5dd9b2d5dffbf6b03a",
