    "exampleHash": "2a61c74aa9a7146f601feff4f126e586a96a92b0fbd9b84dcb8b302a8bdaf94a",
    "qa": "pass",
    "qaDetail": "陶器の艶と毛糸の質感が区別できる、ニット帽をかぶったティーポット。メモラ君と同じ茶卓、文字なし。",
    "sha256": "595048c56e9f792c0737ba60869ff98cd34b96ce76a441c5cba83c441e33331f",
