    "exampleHash": "70782d1b32aaf8c797e2ec89dd5118ebf83c233cf6e52967400740219f4e8ec1",
    "qa": "pass",
    "qaDetail": "同じ大きさの半円形ケーキを一皿ずつ前に置き、メモラ君とタヌキが握手する合意の場面。文字・別枠なし。",
    "sha256": "94945cf878d894fc6ec2c78c1e2470569e6468074f5facc785fbd92b65a45684",
