    "exampleHash": "676b036936d40b5894031dd2365e8aae6026468cfac661330d90a6ae790d7bbc",
    "qa": "pass",
    "qaDetail": "傘店に置かれた実物の木製グラフで、雨の日は傘5本、晴れの日は2本を対応。メモラ君が指し、文字・画面分割なし。",
    "sha256": "9201d790e7e43a93cbefefbabd70791fb8981dea4fc5f176f64d03c1f1c544b9",
