    "exampleHash": "7ab4907a2208bf71a11f93394c10b3574b517d1122e3a927891fd261ce28a22d",
    "qa": "pass",
    "qaDetail": "相談員役モチコシが楽器ケースを持つメモラ君の話を聞く一つの相談室。初舞台の不安が伝わるようメモラ君の表情だけ修正。",
    "sha256": "0bca00a00b336fc29fad056e4e533d7f9c9ddd25156e5f77ad1015ba36d53e84",
