    "exampleHash": "78777a54778337fdea42bd7f876d7b14d22fd488c75e9f6106d29bd205d741ae",
    "qa": "pass",
    "qaDetail": "同一の砂浜でメモラ君の金属検出装置と掘り出されたスプーンをタヌキが確認。地下透視や別場面なし。",
    "sha256": "d49ff4603221a8e90498e7b526f6d8b9597b8cdaf94f94af435338d91cc7a19a",
