    "exampleHash": "c858d13b3200ce2ba076d5476efb4cb1302546cbe6a3d854712c7fbcc0dabf49",
    "qa": "pass",
    "qaDetail": "タヌキが立方体の透明なシャボン玉を吹き、メモラ君が驚く1場面。角張った泡が明瞭で、反応記号なし。",
    "sha256": "e4f0110b21fb9e83c635dc5643ba1a9aa7af02b01a0931af0d3df2d59c075a3a",
