    "exampleHash": "fec8daeab66d85982d0ac0ffb3bc0ee59f425889a2682de40e2d0dc88be1332e",
    "qa": "pass",
    "qaDetail": "巨大なトロフィーを持つドヤモグがメモラ君の小さなトロフィーを見下ろす。2個の所有とサイズ差、無文字を確認。",
