    "exampleHash": "4feef413481bbfe4f5997a8ecd92707ed07f17569951fcc741c9eac485dad6d1",
    "qa": "pass",
    "qaDetail": "タヌキがずれたケーキを指してけなしつつ、食べ終えた皿を差し出す現在の一瞬。メモラ君はサーバーを持ち、過去の食事場面なし。",
    "sha256": "c832d3d2cd7248fe730687783ecb02c1550d04408b7b62b458b72556beb0dbd4",
