    "qa": "pass",
    "qaDetail": "地図を持つメモラ君がごみ箱に到着し、フカシが横に立つ同じ道の場面。地図は経路だけで文字・別の風景描写なし。",
    "sha256": "afcd4897e1fad3246ef317d59a29706dfa6f8172405fded8f638de3e4a9a43f4",
