    "qa": "pass",
    "qaDetail": "泥の付いた一枚の窓で、メモラ君が洗剤と布による清掃効果を試し、タヌキが観察。同じ窓の拭いた部分として表現し、比較パネルなし。",
    "sha256": "d50b4c5321ef83c2584ff88d54bde8e2f1f7669823676d2fe1cf61fe75a92a4a",
