    "qa": "pass",
    "qaDetail": "タヌキの小さなオーブンと焼きたてパンにメモラ君が引き寄せられる一場面。自然な湯気のみ。帽子の余分な右側の房を除去し、左側一本を保持。",
    "sha256": "5dde7cad4bb33c5ea502c4bf7f8f571d7298fe2fa830cda09be621978c4a4d8c",
