    "exampleHash": "dc0b7472b9dcfc4d62089fb4dda2399fc068eacd032953ee0852952263e05a58",
    "qa": "pass",
    "qaDetail": "タヌキが布を引いて青い絵の具のこぼれをさらに広げ、メモラ君が驚く一瞬。手・布・塗料の接触が明瞭。",
    "sha256": "e0e770b2c0041c0f15ad89ef4180bda0c8e28655fd2b64f1f323ff43902ca202",
    "width": 800,
    "height": 533,
