    "exampleHash": "96226bc7c62008cb9da84eee2ecc7626636996900596bad041b5d2ee72e17ed7",
    "qa": "pass",
    "qaDetail": "一台の実物のイーゼルに置かれたティーポットの素描と絵をタヌキが見比べる。物体の絵であり二場面の物語分割ではない。",
    "sha256": "e9497ef28535605efe572b9c5ef753cf8ea804d3268986a21ac16d781c042f40",
