    "qa": "pass",
    "qaDetail": "枕の砦とスリッパ製の跳ね橋が同じ床面でつながる。メモラ君の帽子を房一本に修正、別枠なし。",
    "sha256": "1242b36c8b11b65e68bae62dd18329dd72fb6e0eaf4140eaa18ea6bbcb3e05f2",
