    "qa": "pass",
    "qaDetail": "モチコシが本を選び、虫眼鏡と片方だけのスリッパを同じ読書室に配置。書籍・付箋は無地、想像場面なし。",
    "sha256": "6df8cfd7a6a7e60efeed566f7f0d845d56395a1849ecd56d1374f942d303fce8",
